def build_url(arr):
    toks = set(arr)
    parts = []
    # protocol
    if 'ht' in toks and 'tps' in toks and ':' in toks and '//' in toks:
        parts.append('ht' + 'tps' + '://' )
    # domain code.org
    if 'cod' in toks and 'e.' in toks and 'or' in toks and 'g/' in toks:
        parts.append('cod' + 'e.' + 'or' + 'g/')
    # path to wiki sort
    if 'wiki' in toks and '/' in toks and 'sort' in toks:
        parts.append('wiki' + '/' + 'sort')
    # anchor quicksort and hint to C++
    if '/Q' in toks and 'ksort' in toks and 'C++' in toks:
        parts.append('#' + 'Quick' + 'sort' + '?lang=C++')
    return ''.join(parts)

if __name__ == '__main__':
    print(build_url(arr))

